SELECT s.Name, s.Country, s.Age 
FROM singer s 
ORDER BY s.Age ASC;

SELECT DISTINCT p.Name
FROM poker_player p
ORDER BY COUNT(p.Final_Table_Made) ASC;

SELECT COUNT(DISTINCT PetID)
FROM Pets
WHERE pet_age > 10;

SELECT City, COUNT(Employee_ID) AS Employee_Count
FROM employee
GROUP BY City;

SELECT COUNT(DISTINCT T1.Continent) AS NumCountries
FROM countries AS T1
JOIN continents AS T2 ON T1.Continent = T2.Continent;

SELECT COUNT(DISTINCT T.Template_Type_Code) AS NumberOfTemplates
FROM Templates AS T
JOIN Documents AS D ON T.Template_ID = D.Template_ID;

SELECT T1.CountryId, T2.Model FROM countries AS T1 JOIN car_makers AS T2 ON T1.Continent = T2.Country WHERE T1.CountryId IN (
    SELECT T1.CountryId FROM countries AS T1 JOIN car_makers AS T2 ON T1.Continent = T2.Country WHERE T2.Maker > 3 OR T2.FullName LIKE '%fiat%'
) GROUP BY T1.CountryId

SELECT T.Document_Name, T.Template_ID FROM Documents AS T 
JOIN Templates AS T1 ON T.Template_ID = T1.Template_ID 
WHERE T1.Template_Details LIKE '%w%';

SELECT COUNT(DISTINCT match_num)
FROM matches
WHERE YEAR(tourney_date) IN (2013, 2016);

SELECT DISTINCT T1.country_code FROM players AS T1 JOIN (
    SELECT player_id, COUNT(*) as count FROM matches GROUP BY player_id
) AS T2 ON T1.player_id = T2.player_id
GROUP BY T1.country_code
ORDER BY T1.country_code ASC;

SELECT DISTINCT country_code FROM players WHERE player_id IN (
    SELECT loser_id FROM matches WHERE winner_id IS NULL GROUP BY loser_id HAVING COUNT(*) > 50
)

SELECT DISTINCT country_code FROM players WHERE player_id IN (
    SELECT loser_id FROM matches WHERE round = 'best_of' AND draw_size > 50
)

SELECT T1.first_name, T1.last_name, T2.ranking_points FROM players AS T1 JOIN (
    SELECT winner_id, MIN(winner_rank) as ranking_points FROM matches GROUP BY winner_id
) AS T2 ON T1.player_id = T2.winner_id ORDER BY T2.ranking_points LIMIT 3;

SELECT T1.first_name, T1.last_name, T3.ranking_points FROM players AS T1 JOIN (
    SELECT winner_id, MIN(winner_rank) as ranking FROM matches GROUP BY winner_id
) AS T2 ON T1.player_id = T2.winner_id ORDER BY T2.ranking DESC LIMIT 3
